Item.method_code:
const {
	getState,
	isEditingEnabled,
	itemType,
	rows,
	commandFactory,
	polySources
} = options;

if (!isEditingEnabled) {
	return { hidden: true };
}

const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return itemType;
};

const state = getState();
const visible = state.grid.selectedRows.some((itemId) => {
	const isEditableItem = state.editableItems.has(itemId);
	return !isEditableItem;
});

const commandAlias = target['command_alias@keyed_name'];
const enabled = state.grid.selectedRows.some((itemId) => {
	const item = rows.get(itemId);
	const itemType = getItemType(item);
	const itemTypeName = itemType.name;
	const editCommand = commandFactory(commandAlias, { item, itemType, itemTypeName });
	const canExecute = editCommand.canExecute();
	if (!canExecute) {
		return canExecute;
	}

	const isRelationship = itemType['is_relationship'] === '1';
	const useSrcAccess = itemType['use_src_access'] === '1';
	let isEnableForRelationship = true;
	if (isRelationship && useSrcAccess) {
		const sourceItemType = item['source_id@aras.type'];
		const sourceItemId = item['source_id'];
		isEnableForRelationship = ArasModules.item.isEditState(sourceItemType, sourceItemId);
	}

	const isLockEnabled = !window.isFunctionDisabled(itemTypeName, 'Lock');
	return isLockEnabled && isEnableForRelationship;
});

return {
	disabled: !enabled,
	hidden: !visible
};
